fo[cats], cat: hinfo[cat], body: hbody, line: trtok[line], col: trtok[col]}", "                    if hinfo[any]:", "                        zany = hnode", "                    else:", "                        ztriggers.add(hnode)", "                if len(ztriggers) == 0 AND zany is NONE:", "                    fail(st, trytok, \"SYNTAX_ERROR\", \"trigger after try\", \"finally\")", "                    return stmts", "                if NOT tok_is(tk(st), \"kw\", \"finally\"):", "                    fail(st, tk(st), \"SYNTAX_ERROR\", \"'finally:'\", describe_tok(tk(st)))", "                    return stmts", "                advance(st)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                enter_try_zone(st, zbase)", "                list zfinally = parse_block(st, FALSE)", "                leave_try_zone(st, zbase)", "                if NOT (st[err] is NONE):", "                    return stmts", "                node = {k: \"try\", body: try_body, triggers: ztriggers, any: zany, \"finally\": zfinally, block_stmt: TRUE, line: trytok[line], col: trytok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"for\":", "                dict ftok = advance(st)", "                list nts = []", "                dict nt1 = expect_tok(st, \"name\", \"\", \"loop variable\")", "                nts.add(nt1)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                    dict nt2 = expect_tok(st, \"name\", \"\", \"loop variable\")", "                    nts.add(nt2)", "                if tok_is(tk(st), \"kw\", \"in\"):", "                    advance(st)", "                    dict coll = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    list ftypes = []", "                    str cty = base_type(coll[t])", "                    if cty == \"list\":", "                        if len(nts)