        return stmts", "                    dict rvars = st[vars]", "                    dict rfor = st[for_names]", "                    dict rgv = st[gvars]", "                    if rvars.contains(rname) OR rfor.contains(rname) OR rgv.contains(rname):", "                        fail(st, rnt, \"REDECLARE_ERROR\", \"unique loop variable\", cat([\"name '\", rname, \"' is already declared\"]))", "                        return stmts", "                    rvars.add(rname, \"flint\")", "                    rfor.add(rname, TRUE)", "                    str rlua = mangle_var(st, rname)", "                    dict first = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    dict ftnode = {k: \"for\", name: rname, lua: rlua, line: ftok[line], col: ftok[col]}", "                    if first[k] == \"range\":", "                        ftnode.add(\"form\", \"range\")", "                        if first[kind] == \"float\":", "                            ftnode.add(\"float_fmt\", TRUE)", "                        ftnode.add(\"from\", first[from])", "                        ftnode.add(\"to\", first[to])", "                        if first[has_step]:", "                            ftnode.add(\"step\", first[step])", "                    elif is_numeric(first[t]):", "                        ftnode.add(\"form\", \"upto\")", "                        ftnode.add(\"to\", first)", "                    else:", "                        fail(st, first, \"TYPE_ERROR\", \"loop bound to be flint or range\", first[t])", "                        return stmts", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"loop_depth\", st[loop_depth] + 1)", "                    list rbody = parse_block(st, FALSE)", "                    st.add(\"loop_depth\", st[loop_depth] - 1)", "                    dict rvars2 = st[vars]", "                    rvars2.remove(rname)", "                    ftnode.add(\"body\", rbody)", "                    ftnode.add(\"block_stmt\", TRUE)", "                    node = ftnode", "                    block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"func\":", "                dict prep = prepare_func(st, exported)", "                if NOT (st[err] is NONE):", "                    return stmts", "                begin_func_body(st, prep)", "                list fnbody = parse_block(st, FALSE)", "                node = complete_func(st, prep, fnbody, exported)", "                if NOT (st[err] is NONE):", "                    return stmts", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"model\":", "                dict mtok = advance(st)", "                if st[in_func] OR st[block_depth] > 0:", "                    fail(st, mtok, \"SCOPE_ERROR\", \"model at top level\", \"nested model\")", "                    return stmts", "                dict mnt = expect_tok(st, \"name\", \"\", \"model name\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                str mname = mnt[value]", "                if is_reserved(mname) OR is_const_name(mname):", "                    fail(st, mnt, \"NAME_ERROR\", \"free model name\", cat([\"reserved '\", mname, \"'\"]))", "                    return stmts", "                dict mall = st[models]", "                dict mgv = st[vars]", "                dict mfnc = st[funcs]", "                if mall.contains(mname) OR mgv.contains(mname) OR mfnc.contains(mname):", "                    fail(st, mnt, \"REDECLARE_ERROR\", \"unique model name\", cat([\"name '\", mname, \"' is already declared\"]))", "                    return stmts", "                dict mschema = {name: mname, model_fields: {}, field_types: {}, consts: {}, init_fields: {}, params: [], param_types: {}, methods: {}, method_order: [], ctor: NONE, order: [], field_order: []}", "                mall.add(mname, mschema)