a], \"(\", cp.join(\", \"), \")\"])", "", "    if k == \"list\":", "        list its = e[items]", "        list ip = []", "        for it0 in its:", "            dict itn = it0", "            ip.add(emit_expr(st, itn))", "        return cat([\"krt.list(\\{\", ip.join(\", \"), \"\\})\"])", "", "    if k == \"dict\":", "        list prs = e[pairs]", "        str dx = \"krt.dict()\"", "        for pd0 in prs:", "            dict pd = pd0", "            dict pv = pd[value]", "            str rawk = str(pd[key])", "            str dk = \"\"", "            if pd[ktype] == \"flint\":", "                dk = rawk", "            else:", "                dk = lua_str(rawk)", "            dx = cat([\"krt.dict_set(\", dx, \", \", dk, \", \", emit_expr(st, pv), \")\"])", "        return dx", "", "    if k == \"dget\":", "        dict db = e[base]", "        str rawgk = str(e[key])", "        str gk = \"\"", "        if e[ktype] == \"flint\":", "            gk = rawgk", "        else:", "            gk = lua_str(rawgk)", "        return cat([\"krt.dict_get(\", wrap_dict(emit_expr(st, db), db[t], e_nullable(db)), \", \", gk, \")\"])", "", "    if k == \"index\":", "        dict ib = e[base]", "        dict ii = e[index]", "        str ix = wrap_flint(emit_expr(st, ii), ii[t], e_nullable(ii))", "        str ibb = base_type(ib[t])", "        if ibb == \"list\":", "            return cat([\"krt.list_index(\", wrap_list(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ibb == \"froz\":", "            return cat([\"krt.list_index(\", wrap_froz(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ib[t] == \"any\":", "            return cat([\"krt.index(\", emit_expr(st, ib), \", \", ix, \")\"])", "        return cat([\"krt.str_index(\", wrap_str(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "", "    if k == \"slice\":", "        dict sb = e[base]", "        str sx = emit_expr(st, sb)", "        str sfn = \"str_slice\"